#include <bits/stdc++.h>
using namespace std;

const long long MOD_CONST = 998244353;

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD_CONST;
    while (exp > 0) {
        if (exp & 1) {
            res = (res * base) % MOD_CONST;
        }
        exp >>= 1;
        base = (base * base) % MOD_CONST;
    }
    return res;
}

long long choose(long long n, long long k) {
    long long numerator = 1;
    long long denominator = 1;
    for (long long i = n - k + 1; i <= n; i++) {
        numerator = (numerator * i) % MOD_CONST;
    }
    for (long long i = 1; i <= k; i++) {
        denominator = (denominator * i) % MOD_CONST;
    }
    denominator = power(denominator, MOD_CONST - 2);
    return (numerator * denominator) % MOD_CONST;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int totalN;
    long long totalK;
    cin >> totalN >> totalK;
    if (totalK >= totalN) {
        cout << "0\n";
    } else {
        int kVal = (int) totalK;
        int rVal = totalN - kVal;
        vector<long long> combArray(rVal + 1);
        combArray[0] = 1LL;
        long long numProd = 1LL;
        long long denProd = 1LL;
        for (int i = 1; i <= rVal; i++) {
            numProd = (numProd * (rVal + 1 - i)) % MOD_CONST;
            denProd = (denProd * i) % MOD_CONST;
            combArray[i] = (numProd * power(denProd, MOD_CONST - 2)) % MOD_CONST;
        }
        long long totalAnswer = 0;
        long long flipSign = 1;
        for (int i = 0; i <= rVal; i++) {
            long long term = power((long long)(rVal - i), (long long)totalN);
            totalAnswer += term * flipSign * combArray[i];
            totalAnswer %= MOD_CONST;
            flipSign = -flipSign;
        }
        totalAnswer = (totalAnswer * choose((long long)totalN, (long long)kVal)) % MOD_CONST;
        if (kVal > 0) {
            totalAnswer = (totalAnswer * 2) % MOD_CONST;
        }
        if (totalAnswer < 0) {
            totalAnswer += MOD_CONST;
        }
        cout << totalAnswer << "\n";
    }
    return 0;
}

